<?php namespace App\Http\Controllers;use App\Models\Store;use App\Models\Order;use Illuminate\Http\Request;class StoreController extends Controller{public function landing(){return view('home');}public function show($username){$store=Store::where('username',strtolower($username))->where('published',true)->with(['links','products'])->firstOrFail();return view('store.show',compact('store'));}public function product($username,$product){$store=Store::where('username',strtolower($username))->where('published',true)->firstOrFail();$item=$store->products()->where('slug',$product)->firstOrFail();return view('store.product',compact('store','item'));}public function checkout(Request $r,$username,$product){$store=Store::where('username',strtolower($username))->where('published',true)->firstOrFail();$item=$store->products()->where('slug',$product)->firstOrFail();$d=$r->validate(['customer_name'=>'required|max:120','customer_email'=>'required|email','quantity'=>'required|integer|min:1|max:99']);$order=Order::create(['store_id'=>$store->id,'customer_name'=>$d['customer_name'],'customer_email'=>$d['customer_email'],'amount'=>$item->price*$d['quantity'],'currency'=>$item->currency,'status'=>'pending','payment_provider'=>config('kustore.payment_provider')]);$order->items()->create(['product_id'=>$item->id,'name'=>$item->name,'quantity'=>$d['quantity'],'unit_price'=>$item->price]);return view('store.checkout',compact('store','item','order'));}}